add_action( 'woocommerce_email_before_order_table', 'perfectpixel_content_in_specific_email', 20, 4 );

function perfectpixel_content_in_specific_email( $order, $sent_to_admin, $plain_text, $email ) {
	$ids = array_filter( array_map( 'trim', explode( ',', '{{email_extra_content_ids}}' ) ) );
	if ( ! $email || ! in_array( $email->id, $ids, true ) ) {
		return;
	}
	if ( $plain_text ) {
		echo "\n" . wp_strip_all_tags( '{{email_extra_content}}' ) . "\n\n";
	} else {
		echo '<div class="perfectpixel-email-extra" style="margin-bottom:24px">' . wp_kses_post( '{{email_extra_content}}' ) . '</div>';
	}
}
